#!/usr/bin/env python3
"""
Polish the keygen tune - add intro, better structure
"""

import subprocess
import json
import numpy as np
import base64

def ft2_call(tool, args):
    result = subprocess.run(
        ['ft2', 'call', tool, json.dumps(args)],
        capture_output=True, text=True
    )
    try:
        return json.loads(result.stdout)
    except:
        return None

def generate_sample(sample_type, length=256, freq=440, sample_rate=22050):
    t = np.linspace(0, length/sample_rate, length, dtype=np.float32)

    if sample_type == 'sine':
        wave = np.sin(2 * np.pi * freq * t)
    elif sample_type == 'square':
        wave = np.sign(np.sin(2 * np.pi * freq * t))
    elif sample_type == 'triangle':
        wave = 2 * np.abs(2 * (freq * t - np.floor(freq * t + 0.5))) - 1
        wave = np.clip(wave, -1, 1)
    elif sample_type == 'saw':
        wave = 2 * (freq * t - np.floor(freq * t + 0.5))
        wave = np.clip(wave, -1, 1)
    elif sample_type == 'pulse':
        duty = 0.125
        wave = np.where((freq * t) % 1 < duty, 1.0, -1.0)
    elif sample_type == 'kick':
        t = np.linspace(0, 0.5, int(0.5 * sample_rate), dtype=np.float32)
        freqs = np.linspace(180, 50, len(t))
        phase = np.cumsum(2 * np.pi * freqs / sample_rate)
        wave = np.sin(phase) * np.exp(-t * 5)
        wave = wave[:length] if len(wave) > length else np.pad(wave, (0, length - len(wave)))
    elif sample_type == 'snare':
        noise = np.random.uniform(-1, 1, length)
        env = np.exp(-np.linspace(0, 12, length))
        wave = noise * env
    elif sample_type == 'hihat':
        noise = np.random.uniform(-1, 1, length)
        env = np.exp(-np.linspace(0, 25, length))
        wave = noise * env
    elif sample_type == 'crash':
        noise = np.random.uniform(-1, 1, length)
        env = np.exp(-np.linspace(0, 3, length))
        wave = noise * env
    else:
        wave = np.zeros(length)

    if np.max(np.abs(wave)) > 0:
        wave = wave / np.max(np.abs(wave))
    wave = (wave * 32767).astype(np.int16)
    return wave

print("Creating polished module...")
ft2_call('module_new', {'channels': 8, 'name': 'Keygen Dreams'})

# Classic keygen tempo
ft2_call('song_set', {'bpm': 140, 'speed': 6})

sr = 22050
print("Creating instruments...")

# Lead - bright square
lead_wave = generate_sample('square', 512, 440, sr)
lead_b64 = base64.b64encode(lead_wave.tobytes()).decode('ascii')
ft2_call('sample_create_from_pcm', {
    'instrument': 1, 'sample': 0, 'pcm': lead_b64, 'encoding': 'int16', 'name': 'Lead'
})
ft2_call('instrument_set', {'instrument': 1, 'name': 'Lead'})

# Bass
bass_wave = generate_sample('saw', 512, 55, sr)
bass_b64 = base64.b64encode(bass_wave.tobytes()).decode('ascii')
ft2_call('sample_create_from_pcm', {
    'instrument': 2, 'sample': 0, 'pcm': bass_b64, 'encoding': 'int16', 'name': 'Bass'
})
ft2_call('instrument_set', {'instrument': 2, 'name': 'Bass'})

# Kick
kick_wave = generate_sample('kick', 512, 0, sr)
kick_b64 = base64.b64encode(kick_wave.tobytes()).decode('ascii')
ft2_call('sample_create_from_pcm', {
    'instrument': 3, 'sample': 0, 'pcm': kick_b64, 'encoding': 'int16', 'name': 'Kick'
})
ft2_call('instrument_set', {'instrument': 3, 'name': 'Kick'})

# Snare
snare_wave = generate_sample('snare', 512, 0, sr)
snare_b64 = base64.b64encode(snare_wave.tobytes()).decode('ascii')
ft2_call('sample_create_from_pcm', {
    'instrument': 4, 'sample': 0, 'pcm': snare_b64, 'encoding': 'int16', 'name': 'Snare'
})
ft2_call('instrument_set', {'instrument': 4, 'name': 'Snare'})

# Hi-hat
hihat_wave = generate_sample('hihat', 256, 0, sr)
hihat_b64 = base64.b64encode(hihat_wave.tobytes()).decode('ascii')
ft2_call('sample_create_from_pcm', {
    'instrument': 5, 'sample': 0, 'pcm': hihat_b64, 'encoding': 'int16', 'name': 'HiHat'
})
ft2_call('instrument_set', {'instrument': 5, 'name': 'HiHat'})

# Arp
arp_wave = generate_sample('pulse', 512, 880, sr)
arp_b64 = base64.b64encode(arp_wave.tobytes()).decode('ascii')
ft2_call('sample_create_from_pcm', {
    'instrument': 6, 'sample': 0, 'pcm': arp_b64, 'encoding': 'int16', 'name': 'Arp'
})
ft2_call('instrument_set', {'instrument': 6, 'name': 'Arp'})

# Chord
chord_wave = generate_sample('triangle', 1024, 220, sr)
chord_b64 = base64.b64encode(chord_wave.tobytes()).decode('ascii')
ft2_call('sample_create_from_pcm', {
    'instrument': 7, 'sample': 0, 'pcm': chord_b64, 'encoding': 'int16', 'name': 'Chord'
})
ft2_call('instrument_set', {'instrument': 7, 'name': 'Chord'})

# Crash
crash_wave = generate_sample('crash', 512, 0, sr)
crash_b64 = base64.b64encode(crash_wave.tobytes()).decode('ascii')
ft2_call('sample_create_from_pcm', {
    'instrument': 8, 'sample': 0, 'pcm': crash_b64, 'encoding': 'int16', 'name': 'Crash'
})
ft2_call('instrument_set', {'instrument': 8, 'name': 'Crash'})

print("Building patterns...")

# Pattern 0: Main theme (64 rows)
ft2_call('pattern_set_length', {'pattern': 0, 'rows': 64})
ft2_call('pattern_clear', {'pattern': 0})

# Pattern 1: Variation (64 rows)
ft2_call('pattern_set_length', {'pattern': 1, 'rows': 64})
ft2_call('pattern_clear', {'pattern': 1})

# Lead melody - main theme
melody = [
    (0, 'E-5'), (2, 'D-5'), (4, 'C-5'), (6, 'B-4'),
    (8, 'C-5'), (10, 'D-5'), (12, 'E-5'), (14, 'G-5'),
    (16, 'A-5'), (18, 'G-5'), (20, 'E-5'), (22, 'D-5'),
    (24, 'C-5'), (26, 'B-4'), (28, 'C-5'), (30, 'D-5'),
    (32, 'E-5'), (34, 'F-5'), (36, 'E-5'), (38, 'D-5'),
    (40, 'C-5'), (42, 'B-4'), (44, 'C-5'), (46, 'D-5'),
    (48, 'E-5'), (50, 'D-5'), (52, 'C-5'), (54, 'B-4'),
    (56, 'A-4'), (58, 'B-4'), (60, 'C-5'), (62, 'B-4'),
]

for row, note in melody:
    ft2_call('pattern_set_cell', {
        'pattern': 0, 'row': row, 'channel': 0,
        'note': note, 'instrument': 1
    })

# Arpeggio
arp = [
    (0, 'A-4'), (2, 'C-5'), (4, 'E-5'), (6, 'A-5'),
    (8, 'A-4'), (10, 'C-5'), (12, 'E-5'), (14, 'A-5'),
    (16, 'A-4'), (18, 'C-5'), (20, 'E-5'), (22, 'A-5'),
    (24, 'A-4'), (26, 'C-5'), (28, 'E-5'), (30, 'A-5'),
    (32, 'F-4'), (34, 'A-4'), (36, 'C-5'), (38, 'F-5'),
    (40, 'F-4'), (42, 'A-4'), (44, 'C-5'), (46, 'F-5'),
    (48, 'G-4'), (50, 'B-4'), (52, 'D-5'), (54, 'G-5'),
    (56, 'G-4'), (58, 'B-4'), (60, 'D-5'), (62, 'G-5'),
]

for row, note in arp:
    ft2_call('pattern_set_cell', {
        'pattern': 0, 'row': row, 'channel': 1,
        'note': note, 'instrument': 6
    })

# Bass
bass = [
    (0, 'A-2'), (4, 'A-2'), (8, 'A-2'), (12, 'A-2'),
    (16, 'A-2'), (20, 'A-2'), (24, 'A-2'), (28, 'A-2'),
    (32, 'F-2'), (36, 'F-2'), (40, 'F-2'), (44, 'F-2'),
    (48, 'G-2'), (52, 'G-2'), (56, 'G-2'), (60, 'G-2'),
]

for row, note in bass:
    ft2_call('pattern_set_cell', {
        'pattern': 0, 'row': row, 'channel': 2,
        'note': note, 'instrument': 2
    })

# Drums
for row in range(0, 64, 4):
    ft2_call('pattern_set_cell', {
        'pattern': 0, 'row': row, 'channel': 3,
        'note': 'C-1', 'instrument': 3
    })

for row in [8, 24, 40, 56]:
    ft2_call('pattern_set_cell', {
        'pattern': 0, 'row': row, 'channel': 4,
        'note': 'C-1', 'instrument': 4
    })

for row in range(0, 64, 2):
    ft2_call('pattern_set_cell', {
        'pattern': 0, 'row': row, 'channel': 5,
        'note': 'C-1', 'instrument': 5
    })

# Chords
chords = [(0, 'A-3'), (16, 'A-3'), (32, 'F-3'), (48, 'G-3')]
for row, note in chords:
    ft2_call('pattern_set_cell', {
        'pattern': 0, 'row': row, 'channel': 6,
        'note': note, 'instrument': 7
    })

# Crash on first beat
ft2_call('pattern_set_cell', {
    'pattern': 0, 'row': 0, 'channel': 7,
    'note': 'C-1', 'instrument': 8
})

# Pattern 1: Variation - higher energy
# Same melody but with different bass
bass_var = [
    (0, 'A-2'), (2, 'A-2'), (4, 'A-2'), (6, 'A-2'),
    (8, 'A-2'), (10, 'A-2'), (12, 'A-2'), (14, 'A-2'),
    (16, 'A-2'), (18, 'A-2'), (20, 'A-2'), (22, 'A-2'),
    (24, 'A-2'), (26, 'A-2'), (28, 'A-2'), (30, 'A-2'),
