    (56, 'G-2'), (58, 'G-2'), (60, 'G-2'), (62, 'G-2'),
]

for row, note in bass_var:
    ft2_call('pattern_set_cell', {
        'pattern': 1, 'row': row, 'channel': 2,
        'note': note, 'instrument': 2
    })

# Copy melody to pattern 1
for row, note in melody:
    ft2_call('pattern_set_cell', {
        'pattern': 1, 'row': row, 'channel': 0,
        'note': note, 'instrument': 1
    })

# Copy arp
for row, note in arp:
    ft2_call('pattern_set_cell', {
        'pattern': 1, 'row': row, 'channel': 1,
        'note': note, 'instrument': 6
    })

# Drums for pattern 1
for row in range(0, 64, 4):
    ft2_call('pattern_set_cell', {
        'pattern': 1, 'row': row, 'channel': 3,
        'note': 'C-1', 'instrument': 3
    })

for row in [8, 24, 40, 56]:
    ft2_call('pattern_set_cell', {
        'pattern': 1, 'row': row, 'channel': 4,
        'note': 'C-1', 'instrument': 4
    })

for row in range(0, 64, 2):
    ft2_call('pattern_set_cell', {
        'pattern': 1, 'row': row, 'channel': 5,
